fn replace_with_colon(str1: &Vec<char>) -> Vec<char> {
    let mut out = Vec::with_capacity(str1.len());
    for &ch in str1.iter() {
        let mapped = match ch {
            ' ' | ',' | '.' => ':',
            _ => ch,
        };
        out.push(mapped);
    }
    out
}

